import os
import subprocess
import tempfile
import hashlib
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/var/lib/reports/staging'
ALLOWED_EXTENSIONS = {'.pdf', '.csv', '.xlsx'}

def sanitize_filename(filename):
    """Basic filename sanitization - remove path separators"""
    # Strip directory traversal attempts
    cleaned = filename.replace('..', '').replace('/', '').replace('\\', '')
    return cleaned

def generate_report_id(content):
    return hashlib.md5(content).hexdigest()[:12]

@app.route('/api/v2/reports/convert', methods=['POST'])
def convert_report():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    # Check extension
    _, ext = os.path.splitext(uploaded.filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension {ext} not allowed'}), 400

    # Get conversion format from form data
    output_format = request.form.get('format', 'pdf')
    page_range = request.form.get('pages', 'all')
    orientation = request.form.get('orientation', 'portrait')

    # Save uploaded file
    safe_name = sanitize_filename(uploaded.filename)
    content = uploaded.read()
    report_id = generate_report_id(content)

    input_path = os.path.join(UPLOAD_DIR, f'{report_id}_{safe_name}')
    output_path = os.path.join(UPLOAD_DIR, f'{report_id}_output.{output_format}')

    with open(input_path, 'wb') as f:
        f.write(content)

    # Build conversion command using LibreOffice
    # The page_range parameter is passed to control which pages to convert
    cmd = f'libreoffice --headless --convert-to {output_format}'

    if page_range != 'all':
        # PageRange filter for specific pages
        cmd += f' --infilter="PageRange={page_range}"'

    if orientation == 'landscape':
        cmd += ' --printer-opt="Orientation=landscape"'

    cmd += f' --outdir {UPLOAD_DIR} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        return jsonify({
            'report_id': report_id,
            'output': f'/downloads/{report_id}_output.{output_format}',
            'status': 'completed'
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/v2/reports/status/<report_id>', methods=['GET'])
def report_status(report_id):
    # Validate report_id format
    if not report_id.isalnum() or len(report_id) > 12:
        return jsonify({'error': 'Invalid report ID'}), 400

    output_files = [f for f in os.listdir(UPLOAD_DIR) if f.startswith(report_id)]
    if not output_files:
        return jsonify({'status': 'not_found'}), 404

    return jsonify({'status': 'ready', 'files': output_files})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
